export const code = async (inputs) => {
  const { config, base, inventory, lifecycle, profit, funnel, warehouse } = inputs;
  const sources = { base, inventory, lifecycle, profit, funnel, warehouse };
  for (const [name, source] of Object.entries(sources)) {
    if (source?.meta?.schema_version !== 3 || source.meta.sku_code !== config.sku_code)
      throw new Error(`${name}: unexpected schema or SKU`);
    if (source.meta.period?.as_of !== base.meta.period.as_of || source.meta.period?.time_zone !== base.meta.period.time_zone)
      throw new Error(`${name}: inconsistent context date or time zone`);
  }
  const as_of = base.meta.period.as_of;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(as_of)) throw new Error('Context as_of is required');
  const number = v => v === null || v === undefined || v === '' || typeof v === 'boolean' || !Number.isFinite(Number(v)) ? null : Number(v);
  const metric = (node, key) => Array.isArray(node?.available_metrics) && !node.available_metrics.includes(key) ? null : number(node?.values?.[key]);
  const rows = list => (Array.isArray(list) ? list : []).map(row => ({ ...row,
    values: Object.fromEntries(Object.keys(row.values || {}).map(key => [key, metric(row, key)])) }));
  const current = inventory.current;
  const summary = lifecycle.summary;
  const funnel_periods = rows(funnel.periods);
  const p0 = funnel_periods.find(row => row.period_key === 'P0');
  const pick = (...items) => items.find(item => item.value !== null && item.value !== undefined && item.value !== '') || { value: null, source: null };
  const selection = {
    book_stock: pick({ value: metric(current, 'book_stock'), source: 'inventory.current.values.book_stock' },
      { value: metric(p0, 'sku_ending_inventory'), source: 'sales_funnel.P0.values.sku_ending_inventory' }),
    incoming_quantity: { value: metric(current, 'incoming_quantity'), source: 'inventory.current.values.incoming_quantity' },
    days_in_stock: pick(...['strict_forecast_cover_days', 'turnover_days'].map(key => ({ value: metric(current, key), source: `inventory.current.values.${key}` })),
      { value: metric(summary, 'inventory_cover_days'), source: 'lifecycle.summary.values.inventory_cover_days' }),
    regular_daily_sales: pick({ value: number(current?.strict_forecast?.valid_days) === 0 ? null : metric(current, 'strict_forecast_daily_sales'), source: 'inventory.current.values.strict_forecast_daily_sales' },
      { value: metric(current, 'daily_sales_velocity'), source: 'inventory.current.values.daily_sales_velocity' },
      { value: metric(summary, 'daily_sales_velocity'), source: 'lifecycle.summary.values.daily_sales_velocity' })
  };
  const missing = Object.entries(selection).filter(([, item]) => item.value === null).map(([key]) => key);
  if (!Array.isArray(lifecycle.events)) missing.push('lifecycle_events');
  if (!Array.isArray(inventory.weeks)) missing.push('inventory_history');
  const grade = (summary?.values?.current_grade || base.base?.current_grade || '').toUpperCase() || null;
  const stage = (summary?.values?.current_stage || base.base?.current_stage || '').toUpperCase() || null;
  if (!grade) missing.push('grade');
  if (!['NEW', 'GRW', 'MAT', 'CLR'].includes(stage)) missing.push('stage');
  const values = Object.fromEntries(Object.entries(selection).map(([key, item]) => [key, item.value]));
  for (const [key, value] of Object.entries(values)) if (value !== null && value < 0) throw new Error(`${key}: negative inventory or velocity`);
  const profit_periods = rows(profit.periods);
  for (const row of profit_periods) {
    const span = (Date.parse(row.period_to) - Date.parse(row.period_from)) / 86400000;
    if (span !== 6) throw new Error('Profit periods must be independent seven-day weeks');
  }
  return { sku_code: config.sku_code, as_of, time_zone: base.meta.period.time_zone, grade, stage, ...values,
    strict_daily_sales: number(current?.strict_forecast?.valid_days) === 0 ? null : metric(current, 'strict_forecast_daily_sales'),
    daily_sales_velocity: metric(current, 'daily_sales_velocity') ?? metric(summary, 'daily_sales_velocity'),
    context_total_cover_days: metric(current, 'turnover_days_with_procurement'),
    forecast_valid_days: number(current?.strict_forecast?.valid_days), selection, missing,
    weeks: rows(inventory.weeks), events: Array.isArray(lifecycle.events) ? lifecycle.events : [],
    first_sale_at: summary?.values?.first_sale_at || null, data_started_on: lifecycle.data_started_on || null,
    profit_periods, funnel_periods,
    listings: (Array.isArray(funnel.listings) ? funnel.listings : []).map(listing => ({ ...listing, rows_per_week: rows(listing.rows_per_week) })),
    warehouses: Array.isArray(warehouse.stores) ? warehouse.stores : [],
    source_periods: Object.fromEntries(Object.entries(sources).map(([name, source]) => [name, source.meta.period])),
    inventory_data_through: current?.data_through || null };
};

export const code = async (inputs) => {
  const policy = [inputs.s, inputs.a, inputs.bc, inputs.unknown].find(value => value && typeof value === 'object' && value.shortage_stock !== undefined);
  if (!policy) throw new Error('Grade policy branch did not return a policy');
  return policy;
};

export const code = async ({ data: d, policy }) => {
  const age = date => (Date.parse(d.as_of) - Date.parse(String(date).slice(0, 10))) / 86400000;
  const recent = (type, days) => d.events.some(e => e.event_type === type && age(e.occurred_on) >= 0 && age(e.occurred_on) <= days);
  const reasons = [];
  if (d.days_in_stock !== null && d.days_in_stock < policy.shortage_days) reasons.push('low_cover');
  if (d.book_stock !== null && d.book_stock < policy.shortage_stock) reasons.push('low_stock');
  if (recent('stock_recovered', 14)) reasons.push('stock_recovered_14d');
  if (recent('purchase_received', 7)) reasons.push('purchase_received_7d');
  const calibrated = reasons.length > 0;
  const samples = calibrated ? d.weeks.filter(w => !w.missing && w.values.book_stock !== null && w.values.book_stock >= policy.shortage_stock && w.values.daily_sales_velocity !== null && w.values.daily_sales_velocity >= 0)
    .sort((a, b) => b.week_start.localeCompare(a.week_start)).slice(0, 3) : [];
  const before = samples.length ? Math.max(...samples.map(w => w.values.daily_sales_velocity)) : null;
  const candidates = [before, d.strict_daily_sales, d.daily_sales_velocity].filter(v => v !== null);
  const v_effective = calibrated ? (candidates.length ? Math.max(...candidates) : null) : d.regular_daily_sales;
  return { calibrated, reasons, v_effective, daily_sales_before_shortage: before,
    historical_samples: samples.map(w => ({ week_start: w.week_start, book_stock: w.values.book_stock, daily_sales_velocity: w.values.daily_sales_velocity, is_week_end: w.is_week_end })),
    warnings: calibrated && samples.length < 3 ? ['断货校准可用历史样本不足3周，使用实际可用样本。'] : [] };
};

export const code = async ({ data: d }) => {
  const periods = ['P0', 'P-1', 'P-2'].map(key => d.profit_periods.find(row => row.period_key === key));
  const complete = key => periods.every(row => row?.values?.[key] !== null && row?.values?.[key] !== undefined);
  const sum = key => periods.reduce((total, row) => total + row.values[key], 0);
  const sold = complete('net_sales') ? sum('net_sales') : null;
  const p0 = periods[0]?.values || {};
  const avg_profit_per_unit = sold !== null && sold > 0 && complete('after_tax') ? sum('after_tax') / sold :
    sold !== null && sold <= 0 ? (p0.average_profit_per_order ?? null) : null;
  const unit_goods_cost = sold !== null && sold > 0 && complete('goods_cost') ? sum('goods_cost') / sold : null;
  return { avg_profit_per_unit, unit_goods_cost, net_sales_3_weeks: sold,
    annualized_return_pct: p0.annualized_return_pct ?? null, ad_ratio_pct: p0.ad_ratio_pct ?? null,
    method: sold !== null && sold > 0 ? 'three_week_sales_weighted' : sold !== null ? 'p0_profit_fallback' : 'missing',
    periods: periods.filter(Boolean).map(row => ({ period_key: row.period_key, from: row.period_from, to: row.period_to })),
    missing: [avg_profit_per_unit === null && 'avg_profit_per_unit', unit_goods_cost === null && 'unit_goods_cost'].filter(Boolean) };
};

export const code = async ({ data: d }) => {
  const age = date => (Date.parse(d.as_of) - Date.parse(String(date).slice(0, 10))) / 86400000;
  const incoming_batches = d.events.filter(e => e.event_type === 'purchase_ordered' && e.content?.status === 'ordered' && e.content.expected_arrival_on > d.as_of && e.occurred_on <= d.as_of)
    .sort((a, b) => a.content.expected_arrival_on.localeCompare(b.content.expected_arrival_on))
    .map(e => ({ event_id: e.id, batch_code: e.content.batch_code, quantity: e.content.purchased_quantity ?? null, expected_arrival_on: e.content.expected_arrival_on }));
  const next_arrival = incoming_batches[0] || null;
  const recent_receipt = d.events.some(e => e.event_type === 'purchase_received' && age(e.occurred_on) >= 0 && age(e.occurred_on) <= 14);
  const p0 = d.funnel_periods.find(p => p.period_key === 'P0')?.values.sku_ending_inventory;
  const p1 = d.funnel_periods.find(p => p.period_key === 'P-1')?.values.sku_ending_inventory;
  const inventory_jump = p0 != null && p1 != null && p0 - p1 > 100;
  const low_stock_gate = (d.days_in_stock !== null && d.days_in_stock < 7) || (d.book_stock !== null && d.book_stock < 10);
  const receipt_gate = recent_receipt || inventory_jump;
  const clr_event = d.events.filter(e => e.event_type === 'marketing_state_changed' && String(e.content?.to_stage).toUpperCase() === 'CLR' && e.occurred_on <= d.as_of)
    .sort((a, b) => b.occurred_on.localeCompare(a.occurred_on))[0];
  return { incoming_batches, next_arrival,
    days_until_next_arrival: next_arrival ? -age(next_arrival.expected_arrival_on) : null,
    low_stock_gate, receipt_gate, suppress_overstock: low_stock_gate || receipt_gate,
    clr_entry_date: clr_event?.occurred_on || (d.stage === 'CLR' ? String(d.first_sale_at || d.data_started_on || '').slice(0, 10) || null : null),
    clr_entry_estimated: d.stage === 'CLR' && !clr_event,
    receipt_recovery_advice: receipt_gate && ['S', 'A'].includes(d.grade) && d.stage !== 'CLR' ?
      '新货入库后检查并恢复WB/Ozon站内广告、正常活动销售价，并安排现货向官方仓送货分仓。' : null };
};

export const code = async (inputs) => {
  const policy = [inputs.new, inputs.grw, inputs.mat, inputs.clr, inputs.unknown].find(value => value && typeof value === 'object' && value.kind);
  if (!policy) throw new Error('Stage policy branch did not return a policy');
  return policy;
};

export const code = async ({ data: d, velocity: v, finance: f, events: e, config: c }) => {
  const speed = v.v_effective;
  const canCalculate = d.book_stock !== null && d.incoming_quantity !== null && speed !== null && speed > 0;
  const useContext = !v.calibrated && d.context_total_cover_days !== null;
  const total_cover_days = useContext ? d.context_total_cover_days : canCalculate ? (d.book_stock + d.incoming_quantity) / speed : null;
  const stockout_days_immediate = e.days_until_next_arrival !== null && d.days_in_stock !== null && speed > 0 ? Math.max(0, e.days_until_next_arrival - d.days_in_stock) : null;
  const stockout_date = d.days_in_stock !== null ? new Date(Date.parse(d.as_of) + Math.floor(d.days_in_stock) * 86400000).toISOString().slice(0, 10) : null;
  const missed_profit = stockout_days_immediate !== null && f.avg_profit_per_unit !== null && speed !== null ? stockout_days_immediate * speed * Math.max(0, f.avg_profit_per_unit) : null;
  const weekly_loss = f.avg_profit_per_unit !== null && speed !== null ? speed * Math.max(0, f.avg_profit_per_unit) * 7 : null;
  const alerts = [];
  if (total_cover_days !== null && total_cover_days < c.lead_time_days) alerts.push({ type: '补货预警', level: 'red',
    message: `全链覆盖${total_cover_days.toFixed(1)}天，距${c.lead_time_days}天供应周期缺${(c.lead_time_days - total_cover_days).toFixed(1)}天。`,
    advice: '立即启动采购排产，并核实到货节奏。', evidence: { total_cover_days, lead_time_days: c.lead_time_days } });
  if (stockout_days_immediate > 0) alerts.push({ type: '到货前断货', level: weekly_loss >= 2000 ? 'red' : 'yellow',
    message: `预计${stockout_date}库存耗尽，下一批${e.next_arrival.expected_arrival_on}到达，间隔${stockout_days_immediate.toFixed(1)}天。`,
    advice: f.avg_profit_per_unit < 0 ? '当前单件亏损，断货在财务上减少亏损；补货前核实盈利能力。' : '协调现有在途到货和可用渠道调拨，降低近期断档。',
    evidence: { stockout_days_immediate, missed_profit, weekly_loss, profit_impact: f.avg_profit_per_unit < 0 ? 'loss_reduction' : f.avg_profit_per_unit === null ? 'unknown' : 'lost_profit' } });
  return { total_cover_days, cover_source: useContext ? 'context.turnover_days_with_procurement' : canCalculate ? 'calibrated_or_missing_metric_formula' : 'missing',
    stockout_date, stockout_days_immediate, missed_profit, weekly_loss,
    lead_time_gap: total_cover_days !== null ? Math.max(0, c.lead_time_days - total_cover_days) : null,
    buffer_days: total_cover_days !== null ? Math.max(0, total_cover_days - c.lead_time_days) : null,
    gap_explanation: total_cover_days !== null && total_cover_days < c.lead_time_days && stockout_days_immediate > 0 ?
      '90天总供给缺口与首轮到货前断档重叠，后续在途耗尽还可能形成次轮断档；两者不可直接相加。' : null,
    alerts, missing: [total_cover_days === null && 'total_cover_days', stockout_days_immediate === null && d.incoming_quantity > 0 && 'immediate_gap_arrival_or_cover'].filter(Boolean) };
};

export const code = async ({ data: d, velocity: v, finance: f, supply: s, config: c, events: e, stage_policy: p }) => {
  if (s.total_cover_days === null) return { suggested_quantity: null, target_days: null, status: 'insufficient_data', reason: '缺少全链覆盖或有效日销，暂不能确定补货量。' };
  if (s.total_cover_days >= c.lead_time_days) return { suggested_quantity: 0, target_days: 0, status: 'covered', reason: `当前覆盖完整供应周期，可在${s.buffer_days.toFixed(1)}天缓冲内启动下一批排产。` };
  const priority = ['S', 'A'].includes(d.grade) || f.annualized_return_pct > c.high_return_pct;
  const target_days = priority ? p.priority_target_days : p.standard_target_days;
  const raw_quantity = target_days * v.v_effective;
  const past = d.events.filter(event => event.event_type === 'purchase_ordered' && event.occurred_on <= d.as_of && event.content?.purchased_quantity != null && Number(event.content.purchased_quantity) > 0)
    .sort((a, b) => b.occurred_on.localeCompare(a.occurred_on));
  const standard_lot = past.length ? Number(past[0].content.purchased_quantity) : null;
  const near_lot = standard_lot ? Math.max(1, Math.round(raw_quantity / standard_lot)) * standard_lot : null;
  const round_to_lot = near_lot !== null && Math.abs(near_lot - raw_quantity) / raw_quantity <= c.lot_rounding_tolerance && !(d.stage === 'NEW' && near_lot > raw_quantity);
  const suggested_quantity = round_to_lot ? Math.ceil(near_lot) : Math.ceil(raw_quantity);
  const finance_review = f.avg_profit_per_unit < 0 || (f.annualized_return_pct !== null && f.annualized_return_pct < c.low_return_pct);
  return { suggested_quantity, raw_quantity, target_days, standard_lot, rounded_to_lot: round_to_lot,
    status: finance_review ? 'review_profit_before_order' : 'replenish', finance_review,
    reason: `按新批次到货后${target_days}天动销备货：${target_days} × ${v.v_effective.toFixed(4)} = ${raw_quantity.toFixed(1)}件，建议${suggested_quantity}件。交期内损失销量不再重复计入；之后每月按约${c.normal_monthly_days}天动销复核采购。`,
    warning: finance_review ? '当前利润或年化回报不足，确认补货收益后再下单。' : f.avg_profit_per_unit === null || f.annualized_return_pct === null ? '利润或年化回报缺失，采购前补充核实。' : null,
    next_arrival: e.next_arrival };
};

export const code = async ({ data: d }) => {
  const number = v => v === null || v === undefined || v === '' || !Number.isFinite(Number(v)) ? null : Number(v);
  const channels = [], alerts = [], missing = [];
  for (const listing of d.listings) {
    const p0 = listing.rows_per_week.find(row => row.period_key === 'P0');
    const values = p0?.values || {};
    const warehouse = d.warehouses.find(store => store.store_id === listing.store_id && store.platform === listing.platform && store.data_status === 'available');
    const fbo = number(warehouse?.summary?.available) ?? (listing.platform === 'wb' ? (values.wb_stock ?? null) : null);
    const fbs = number(warehouse?.summary?.fbs_available) ?? (listing.platform === 'wb' ? (values.wb_seller_stock ?? null) : null);
    const demand = (values.orders ?? 0) > 0 || (values.cart_additions ?? 0) > 0;
    let status = fbo === null || fbs === null ? 'insufficient_data' : fbo <= 2 && fbs <= 2 ? 'channel_stockout' : fbo <= 2 && fbs > 2 ? 'fbs_fallback' : 'available';
    if (status === 'insufficient_data') missing.push(`channel_stock:${listing.store_ref}`);
    const top_clusters = (warehouse?.sales_clusters || []).filter(cluster => number(cluster.distribution_gap) > 0)
      .sort((a, b) => b.distribution_gap - a.distribution_gap).slice(0, 5)
      .map(cluster => ({ cluster_name: cluster.cluster_name, suggested_quantity: cluster.distribution_gap }));
    const channel = { platform: listing.platform, store_id: listing.store_id, store_name: listing.store_name, status,
      fbo_stock: fbo, fbs_stock: fbs, stock_source: warehouse ? 'warehouse_recommendation.current' : 'funnel.P0',
      distribution_gap: number(warehouse?.summary?.distribution_gap), top_clusters,
      days_of_stock: number(warehouse?.summary?.days_of_stock), daily_sales: number(warehouse?.summary?.daily_sales) };
    channels.push(channel);
    if (status === 'fbs_fallback') alerts.push({ type: '渠道失衡', level: 'yellow',
      message: `${listing.platform.toUpperCase()} ${listing.store_name}官方仓库存${fbo}件，商品未断货，由白俄本地仓FBS兜底；配送通常慢2～4天，可能影响转化和搜索排位。`,
      advice: '按官方仓分布缺口安排送仓，优先核心销售集群；FBS挂载库存不能跨Listing相加为物理库存。', evidence: channel });
    if (status === 'channel_stockout' && demand) alerts.push({ type: '渠道失衡', level: 'yellow',
      message: `${listing.platform.toUpperCase()} ${listing.store_name}官方仓与FBS均接近售罄，近期仍有销售或加购需求。`,
      advice: d.days_in_stock !== null && d.days_in_stock >= 28 ? '立即从白俄总仓向该渠道配货。' : '核实其他渠道冗余现货，评估跨平台紧急调拨。', evidence: channel });
  }
  if (!d.listings.length) missing.push('channel_listings');
  return { channels, alerts, missing, unallocated_stock: null,
    limitation: '各Listing的FBS可能重复挂载同一白俄物理库存，当前API没有可去重的分配明细，不能用book_stock减Listing现货总和计算未铺发库存。' };
};

export const code = async ({ data: d, velocity: v, events: e, supply: s, channels: ch }) => {
  if (e.suppress_overstock) return { suppressed: true, reasons: [e.low_stock_gate && 'near_stockout', e.receipt_gate && 'receipt_14d_protection'].filter(Boolean), alerts: [], recovery_advice: e.receipt_recovery_advice };
  const alerts = [];
  if (s.total_cover_days > 180) alerts.push({ type: '库存积压', level: 'red', message: `全链库存覆盖${s.total_cover_days.toFixed(1)}天，超过180天。`, advice: '压缩后续排产并评估促销去库存。' });
  if (v.v_effective === 0 && d.book_stock > 0) alerts.push({ type: '库存积压', level: 'yellow', message: '有在库库存但有效日销为0。', advice: '排查链接、价格和投放，并核实库存去化方案。' });
  for (const channel of ch.channels) {
    if (channel.fbo_stock > 0 && channel.days_of_stock > 90) alerts.push({ type: '库存积压', level: 'yellow', message: `${channel.platform.toUpperCase()}官方仓周转超过90天。`, advice: '核实平台超期仓储费风险并优化官方仓存量。', evidence: channel });
    const listing = d.listings.find(row => row.store_id === channel.store_id && row.platform === channel.platform);
    const history = listing?.rows_per_week || [];
    const dormant = history.length >= 3 && history.every(row => row.values.orders === 0);
    if (channel.fbo_stock === 0 && channel.fbs_stock > 0 && dormant) alerts.push({ type: '动销异常 · 渠道 Listing 休眠', level: 'yellow', message: `${channel.platform.toUpperCase()}仅FBS挂载库存，多个周期没有订单。`, advice: '排查链接屏蔽、定价和广告；白俄FBS库存不产生平台仓储费。', evidence: channel });
  }
  return { suppressed: false, reasons: [], alerts };
};

export const code = async ({ data: d, velocity: v, config: c }) => {
  const applicable = ['S', 'A'].includes(d.grade) && ['NEW', 'GRW'].includes(d.stage);
  if (!applicable) return { applicable: false, alerts: [] };
  const speed = v.v_effective;
  const total_cover_days = d.book_stock !== null && d.incoming_quantity !== null && speed > 0 ? (d.book_stock + d.incoming_quantity) / (1.3 * speed) : null;
  return { applicable, scenario: 'daily_sales_plus_30_pct', total_cover_days,
    shortage_risk: total_cover_days === null ? null : total_cover_days < c.lead_time_days,
    alerts: total_cover_days !== null && total_cover_days < c.lead_time_days ? [{ type: '销量增长压力测试', level: 'yellow', message: `销量增长30%时覆盖${total_cover_days.toFixed(1)}天，低于${c.lead_time_days}天。`, advice: '将增长情景单独纳入安全库存评估，保持基准指标独立。' }] : [] };
};

export const code = async ({ data: d, velocity: v, events: e }) => {
  const total = d.book_stock !== null && d.incoming_quantity !== null ? d.book_stock + d.incoming_quantity : null;
  const deadline = e.clr_entry_date ? new Date(Date.parse(e.clr_entry_date) + 90 * 86400000).toISOString().slice(0, 10) : null;
  const days_left = deadline ? (Date.parse(deadline) - Date.parse(d.as_of)) / 86400000 : null;
  const days_to_clear = total !== null && v.v_effective > 0 ? total / v.v_effective : null;
  const overdue_days = days_to_clear !== null && days_left !== null ? days_to_clear - days_left : null;
  const alerts = [];
  const stalled = total > 0 && v.v_effective === 0;
  if (total !== 0 && (stalled || overdue_days > 0)) alerts.push({ type: '清库超期', level: stalled || overdue_days > 30 ? 'red' : 'yellow',
    message: stalled ? '清库库存仍有剩余，但销售停滞。' : `按当前动销预计超过清库期限${overdue_days.toFixed(1)}天。`,
    advice: '调整清仓价格与渠道配置，按固定90天清仓周期复核进度。' });
  return { clearance_total: total, clr_entry_date: e.clr_entry_date, clr_entry_estimated: e.clr_entry_estimated,
    latest_clearance_date: deadline, days_left, days_to_clear, overdue_days, stalled, completed: total === 0, alerts,
    missing: [total === null && 'clearance_total', !deadline && 'clr_entry_date', v.v_effective === null && 'v_effective'].filter(Boolean) };
};

export const code = async ({ finance: f, clearance: c }) => {
  const total_goods_cost = c.clearance_total !== null && f.unit_goods_cost !== null ? c.clearance_total * f.unit_goods_cost : null;
  const raw_projected_profit = c.clearance_total !== null && f.avg_profit_per_unit !== null ? c.clearance_total * f.avg_profit_per_unit : null;
  const loss_ratio = f.avg_profit_per_unit < 0 && f.unit_goods_cost > 0 ? Math.abs(f.avg_profit_per_unit) / f.unit_goods_cost : null;
  const ad_distortion = f.avg_profit_per_unit < 0 && ((f.ad_ratio_pct !== null && f.ad_ratio_pct > 25) || (f.unit_goods_cost !== null && Math.abs(f.avg_profit_per_unit) > f.unit_goods_cost));
  const alerts = [];
  if (c.clearance_total > 0 && ad_distortion) alerts.push({ type: '广告空转失血', level: 'red',
    message: '广告费占比或单件亏损命中失真保护；需核查低动销下广告费用分摊，不能据此直接认定商品刚性亏损。',
    advice: '暂停或大幅调低付费广告，将预算转为清仓折让；如白俄总仓有可用现货，可小批量20～30件送往官方仓。' });
  else if (c.clearance_total > 0 && f.avg_profit_per_unit < 0) alerts.push({ type: '清库亏损', level: loss_ratio > 0.3 ? 'red' : 'yellow',
    message: loss_ratio !== null ? `按平滑利润测算，清库亏损约占货值${(loss_ratio * 100).toFixed(1)}%。` : '当前平滑单件利润为负，货值成本不足以核算亏损率。', advice: '核实清仓价格底线与可接受亏损预算。' });
  return { total_goods_cost, raw_projected_profit, loss_ratio, ad_distortion, alerts,
    limitation: ad_distortion ? '广告失真时账面预计损益仅作原始证据，不作为真实清库亏损预测。' : null };
};

export const code = async (inputs) => {
  const { data: d, velocity: v, finance: f, events: e } = inputs;
  const objects = [inputs.supply, inputs.replenishment, inputs.channels, inputs.overstock, inputs.stress, inputs.clearance, inputs.clearance_finance].filter(x => x && typeof x === 'object');
  const missing = [...new Set([...d.missing, ...f.missing, ...objects.flatMap(x => x.missing || []), ...(v.v_effective === null ? ['v_effective'] : [])])];
  const rank = { red: 2, yellow: 1, green: 0 };
  const alerts = objects.flatMap(x => x.alerts || []).sort((a, b) => (b.type === '补货预警') - (a.type === '补货预警') || rank[b.level] - rank[a.level]);
  const supply = inputs.supply || {};
  const clr = inputs.clearance || {};
  const replenishment = inputs.replenishment || {};
  const unknown_stage = !['NEW', 'GRW', 'MAT', 'CLR'].includes(d.stage);
  const risk_level = alerts.some(x => x.level === 'red') ? 'red' : alerts.length || missing.length ? 'yellow' : 'green';
  const round = value => typeof value === 'number' && Number.isFinite(value) ? Math.round(value * 10000) / 10000 : value ?? null;
  const metrics = Object.fromEntries(Object.entries({ book_stock: d.book_stock, incoming_quantity: d.incoming_quantity,
    v_effective: v.v_effective, days_in_stock: d.days_in_stock, total_cover_days: d.stage === 'CLR' ? clr.days_to_clear : supply.total_cover_days,
    next_arrival_date: e.next_arrival?.expected_arrival_on, next_arrival_quantity: e.next_arrival?.quantity,
    stockout_days_immediate: supply.stockout_days_immediate, missed_profit_cny: supply.missed_profit,
    lead_time_gap: supply.lead_time_gap, buffer_days: supply.buffer_days,
    suggested_replenishment_quantity: d.stage === 'CLR' ? 0 : replenishment.suggested_quantity,
    replenishment_target_days: replenishment.target_days, avg_profit_per_unit_cny: f.avg_profit_per_unit,
    annualized_return_pct: f.annualized_return_pct, clearance_total: clr.clearance_total,
    latest_clearance_date: clr.latest_clearance_date, days_to_clear: clr.days_to_clear, overdue_days: clr.overdue_days }).map(([k, value]) => [k, round(value)]));
  const labels = { book_stock: '当前库存', incoming_quantity: '在途库存', v_effective: '基准日销', days_in_stock: '在库覆盖天数', total_cover_days: '全链覆盖天数', next_arrival_date: '最近预计到货日', suggested_replenishment_quantity: '建议补货量' };
  const markdown = [`# ${d.sku_code} 库存诊断`, `Grade / Stage：${d.grade || '缺失'} / ${d.stage || '缺失'}`, `基准日期：${d.as_of}（${d.time_zone}）`,
    `综合风险：${{ red: '红', yellow: '黄', green: '绿' }[risk_level]}；诊断标签：${[...new Set(alerts.map(x => x.type))].join('、') || (missing.length ? '数据不足' : '未命中风险')}`,
    '', '| 指标 | 数值 |', '| --- | --- |', ...Object.entries(labels).map(([key, label]) => `| ${label} | ${metrics[key] ?? '数据缺失'} |`), '',
    ...alerts.flatMap(x => [`## ${x.type}`, x.message, x.advice,
      x.type === '到货前断货' && metrics.missed_profit_cny !== null ? `预计错失利润：${metrics.missed_profit_cny}元；按三周平滑单件净利测算。` : '',
      x.type === '渠道失衡' && x.evidence?.distribution_gap > 0 ? `官方仓分布缺口：${x.evidence.distribution_gap}件；优先集群：${x.evidence.top_clusters.map(c => `${c.cluster_name} ${c.suggested_quantity}件`).join('、')}。` : '', '']),
    replenishment.reason || '', replenishment.warning || '',
    supply.gap_explanation || '', e.clr_entry_estimated ? '清仓起点为估算值。' : '',
    missing.length ? `数据缺口：${missing.join('、')}。` : '', ...v.warnings].filter(x => x !== null).join('\n');
  return { sku_code: d.sku_code, as_of: d.as_of, time_zone: d.time_zone, grade: d.grade, stage: d.stage,
    status: missing.length || unknown_stage ? 'insufficient_data' : 'completed', risk_level, tags: [...new Set(alerts.map(x => x.type))],
    metrics, alerts, missing, markdown, evidence: { selection: d.selection, source_periods: d.source_periods,
      inventory_data_through: d.inventory_data_through, velocity: v, finance: f, arrivals: e, supply, replenishment,
      channel_health: inputs.channels || null, overstock: inputs.overstock || null, stress: inputs.stress || null,
      clearance: inputs.clearance || null, clearance_finance: inputs.clearance_finance || null } };
};
